package solution

import (
	"math"
	"math/big"
	"testing"
)

func expectedCollectionPercent(live, target uint64) int {
	if target <= live {
		return 0
	}
	difference := new(big.Int).Sub(new(big.Int).SetUint64(target), new(big.Int).SetUint64(live))
	difference.Mul(difference, big.NewInt(100))
	difference.Div(difference, new(big.Int).SetUint64(live))
	if difference.Cmp(big.NewInt(10000)) > 0 {
		return 10000
	}
	return int(difference.Int64())
}

func TestCollectionPercentZeroLiveIsError(t *testing.T) {
	for _, target := range []uint64{0, 1, math.MaxUint64} {
		got, err := CollectionPercent(0, target)
		if err == nil || got != 0 {
			t.Fatalf("CollectionPercent(0, %d) = %d, %v; want 0 and error", target, got, err)
		}
	}
}

func TestCollectionPercentAtOrBelowLive(t *testing.T) {
	for _, tc := range []struct{ live, target uint64 }{{1, 0}, {1, 1}, {math.MaxUint64, math.MaxUint64}, {100, 99}} {
		got, err := CollectionPercent(tc.live, tc.target)
		if err != nil || got != 0 {
			t.Fatalf("CollectionPercent(%d, %d) = %d, %v; want 0, nil", tc.live, tc.target, got, err)
		}
	}
}

func TestCollectionPercentFloorClampAndOverflowSafety(t *testing.T) {
	cases := []struct{ live, target uint64 }{
		{100, 101},
		{3, 4},
		{3, 5},
		{100, 150},
		{1, 101},
		{1, 102},
		{1, math.MaxUint64},
		{2, math.MaxUint64},
		{math.MaxUint64 - 1, math.MaxUint64},
		{math.MaxUint64 / 2, math.MaxUint64},
		{math.MaxUint64/101 + 1, math.MaxUint64},
	}
	for _, tc := range cases {
		want := expectedCollectionPercent(tc.live, tc.target)
		got, err := CollectionPercent(tc.live, tc.target)
		if err != nil || got != want {
			t.Errorf("CollectionPercent(%d, %d) = %d, %v; want %d, nil", tc.live, tc.target, got, err, want)
		}
	}
}

package solution

import "testing"

func TestReviewUint64Percent0180(t *testing.T) {
	got, err := CollectionPercent(uint64(1)<<63, ^uint64(0))
	if err != nil || got != 99 { t.Fatalf("percent=%v err=%v, want 99", got, err) }
}

