package solution

import "errors"

func CollectionPercent(liveBytes, targetBytes uint64) (int, error) {
    if liveBytes == 0 {
        return 0, errors.New("live size must be positive")
    }
    if targetBytes <= liveBytes {
        return 0, nil
    }
    delta := targetBytes - liveBytes
    quotient := delta / liveBytes
    remainder := delta % liveBytes
    if quotient >= 100 {
        return 10000, nil
    }
    percent := quotient*100 + remainder*100/liveBytes
    if percent > 10000 {
        percent = 10000
    }
    return int(percent), nil
}

